import {
  type Menu as MenuController,
  type MenuItemInput,
  type MenuVariant,
  createMenu,
} from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createContext, createEffect, merge, omit, onSettled, untrack, useContext } from "solid-js";

import { Button } from "./button.tsx";
import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

/**
 * The checkable state, readable: checkbox items that are checked, and the chosen radio, by index. The primitive takes
 * the same pair (`checked` / `choice`), so the kit passes it straight through and a caller never writes an encoding; any
 * checkbox item can be controlled, not just item 0.
 */
export interface MenuChecked {
  /** The checked checkbox items, by index. */
  readonly checked: ReadonlyArray<number>;
  /** The chosen radio item, by index; `-1` or absent means none. */
  readonly radio?: number;
}

export interface MenuProps {
  /** The items, declared once: the primitive needs the labels for typeahead, and the ids come from here. */
  readonly items: ReadonlyArray<string | MenuItemInput>;
  /**
   * The primitive's variant: `plain` by default; `checkbox-items`, `radio-items` or `mixed` gives each item its role by
   * index (the primitive's rule, not a `kind` on the item).
   */
  readonly variant?: MenuVariant;
  /** Controlled checked items; leave it out and the menu owns them. */
  readonly value?: MenuChecked | undefined;
  /** Uncontrolled checked items at mount; ignored while `value` is set. */
  readonly defaultValue?: MenuChecked;
  /** A request to change the checked items. A plain item is `onItemClick`, not this. */
  readonly onValueChange?: (value: MenuChecked) => void;
  /** Controlled: the host owns the open state and this is the only thing that opens or closes it. */
  readonly open?: boolean;
  /** Open at mount; ignored while `open` is set. */
  readonly defaultOpen?: boolean;
  /** A request to change the open state: uncontrolled it is accepted, controlled the host may ignore it. */
  readonly onOpenChange?: (open: boolean) => void;
  /** An item was activated: its index in `items`. */
  readonly onItemClick?: (index: number) => void;
  /** Item indices that stay focusable and never activate. */
  readonly disabled?: ReadonlyArray<number>;
  readonly id?: string;
  /** The primitive, once: a page that drives the menu from elsewhere. */
  readonly onReady?: (menu: MenuController) => void;
  /**
   * The primitive's provider: `"auto"` (the native `focusgroup` where the engine has it) by default;
   * `"polyfill"` forces `@microsoft/focusgroup-polyfill`, which the conformance fixture needs because its
   * `key` steps are untrusted events and its probe reads the rendered `tabindex`.
   */
  readonly provider?: "auto" | "polyfill";
  readonly children?: JSX.Element;
}

export type MenuTriggerPartProps = PartProps;

export interface MenuTriggerProps extends Renderable<MenuTriggerPartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export interface MenuContentProps extends Renderable<PartProps, void> {
  readonly class?: string;
  /** Rows of your own; without children the declared items are the rows, in order. */
  readonly children?: JSX.Element;
}

/** What a row's `render` sees: where the highlight is, whether the item activates, and whether it is checked. */
export interface MenuItemState {
  readonly highlighted: () => boolean;
  readonly disabled: () => boolean;
  /** The primitive's `aria-checked` is `true`; always `false` on a plain item. */
  readonly checked: () => boolean;
}

export type MenuItemPartProps = PartProps;

export interface MenuItemProps extends Renderable<MenuItemPartProps, MenuItemState> {
  /** The index in the menu's `items` this row is: the primitive owns the id, the role and the roving tab stop. */
  readonly index: number;
  readonly class?: string;
  /** The row's content; the declared label by default. */
  readonly children?: JSX.Element;
}

const MenuContext = createContext<{
  readonly menu: MenuController;
  /** A checkable variant: every row reserves the mark's column, so a mixed menu's plain rows line up. */
  readonly checkable: boolean;
}>();

// The anchor is the decision this component makes about floating: one box around the trigger and the menu, `position:
// relative`, and the content is `position: absolute` in it. No measurement, no listener on scroll or resize, and the
// content moves with the trigger for free. The cost is the wrapper (a box the caller's layout did not have) and any
// `overflow: hidden` ancestor clips the menu; a real floating layer is the wayfinder entry's "left".
const anchorClass = css.cn(css.position("relative"), css.display("inline-flex"));

const contentClass = css.cn(
  css.position("absolute"),
  css.insetBlockStart("100%"),
  css.insetInlineStart("0"),
  css.marginBlockStart(t.space._1),
  // `z-index` takes an `<integer>`, which a `number` token is not: like Dialog, the class reads the token by hand
  css.zIndex("var(--z-popover)"),
  css.minWidth("max-content"),
  // no `display`: the primitive hides the menu with the `hidden` attribute, and a display declaration in this class would
  // override the UA's `[hidden] { display: none }` (the rows are block-level flex boxes, so they stack anyway)
  css.padding(t.space._1),
  css.bg(t.color.overlayBackground),
  css.color(t.color.text),
  css.border("1px solid", t.color.overlayBorder),
  css.borderRadius(t.radius.lg),
  css.boxShadow(t.shadow.popover),
);

// The highlight is the row the primitive announces (`data-highlighted`, mirrored from `focusIndex`), not a second copy of
// the state: a pointer hover and an arrow key both move it. The row is a `<button>` because an item has to be focusable for
// the platform's `focusgroup` to move focus to it — the native engine writes no `tabindex`, so a `div` would never receive
// the focus — and a menu item is an action anyway.
const itemClass = css.cn(
  // the marker `within()` reads: the row's own `aria-checked` is what the mark follows
  css.group(),
  css.display("flex"),
  css.alignItems("center"),
  css.width("100%"),
  css.boxSizing("border-box"),
  css.padding(t.space._1, t.space._2),
  css.border("none"),
  css.borderRadius(t.radius.sm),
  css.bg("transparent"),
  css.fontFamily("inherit"),
  css.fontSize(t.font.size),
  css.textAlign("start"),
  css.color(t.color.text),
  css.cursor("pointer"),
  css.attr("data-highlighted", "true")(css.bg(t.color.buttonBackground)),
  css.attr("aria-disabled", "true")(css.color(t.color.textDisabled), css.cursor("not-allowed")),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("-2px")),
);

// The check is the primitive's `aria-checked` and nothing else: hidden by default, shown only inside a row that says it is
// checked, so the kit keeps no copy of the state. Its width is reserved in a checkable menu, so labels do not shift when a
// box is ticked.
const markClass = css.cn(
  css.width("1em"),
  css.flexShrink(0),
  css.marginInlineEnd(t.space._1),
  css.fontSize("0.75rem"),
  css.color(t.color.muted),
  css.visibility("hidden"),
  css.within(css.attr("aria-checked", "true"))(css.visibility("visible")),
);

/** A part by the id the primitive gave it: a `render` may rename `data-part`, the id is the primitive's. */
const byId = (id: string): HTMLElement | undefined => document.getElementById(id) ?? undefined;

/**
 * APG menu button, styled: `Menu.Trigger` (a `Button`) opens `Menu.Content`, a list of `Menu.Item`s with one roving focus
 * and one tab stop. `createMenu` owns the open state, the ARIA, the movement through the platform's `focusgroup`
 * (`focusgroup="menu"`: the arrows, Home / End, the wrap and the item `tabindex`), Escape, the typeahead buffer and the
 * keys across the axis; the kit adds the anchor the content floats from, the surface, the highlight and the DOM focus, and
 * closes the menu on a click outside.
 *
 * `open` makes it controlled: then every intent (the trigger, a key, Escape, an item, a click outside) is a request the
 * host may ignore, and `open` is the only thing that moves. Without it the primitive owns the state from `defaultOpen`.
 *
 * The items are declared on `Menu`, once: the primitive needs their labels, so a row names its item by `index` instead of
 * repeating the label. One level only — no submenus, no separators (the primitive has none). `variant` turns the rows into
 * checkbox and radio items; Space toggles one without closing, Enter toggles and closes, and a radio clears its group.
 */
export const Menu = (props: MenuProps): JSX.Element => {
  const menu: MenuController = createMenu({
    items: props.items,
    variant: props.variant,
    get checked() {
      return props.value?.checked;
    },
    get choice() {
      return props.value === undefined ? undefined : (props.value.radio ?? -1);
    },
    get defaultChecked() {
      return props.defaultValue?.checked;
    },
    get defaultChoice() {
      return props.defaultValue?.radio;
    },
    get onCheckedValuesChange() {
      const change = props.onValueChange;
      return change === undefined
        ? undefined
        : (checked: ReadonlyArray<number>, choice: number) => {
            change({ checked, radio: choice });
          };
    },
    get open() {
      return props.open;
    },
    defaultOpen: props.defaultOpen,
    disabled: props.disabled,
    id: props.id,
    get onOpenChange() {
      return props.onOpenChange;
    },
    get onItemClick() {
      return props.onItemClick;
    },
    get provider() {
      return props.provider;
    },
  });
  untrack(() => props.onReady)?.(menu);
  let anchor: HTMLDivElement | undefined;
  // A pointerdown outside the anchor is the dismiss the primitive does not own: it has no document listener, and the
  // trigger's own click is inside the anchor, so the toggle still works. It is a close *request*, so a host that holds
  // `open` keeps the menu.
  onSettled(() => {
    const dismiss = (event: PointerEvent): void => {
      if (anchor !== undefined && event.target instanceof Node && !anchor.contains(event.target)) {
        menu.leave();
      }
    };
    document.addEventListener("pointerdown", dismiss);
    return () => document.removeEventListener("pointerdown", dismiss);
  });
  return (
    <MenuContext
      value={{
        menu,
        checkable: props.variant !== undefined && props.variant !== "plain",
      }}
    >
      <div
        data-part="menu-anchor"
        class={anchorClass}
        ref={(element: HTMLDivElement) => {
          anchor = element;
        }}
      >
        {props.children}
      </div>
    </MenuContext>
  );
};

/** The button that opens the menu: `Button` unless `render` says otherwise. It is the element with `aria-haspopup`. */
export const MenuTrigger = (props: MenuTriggerProps): JSX.Element => {
  const { menu } = useContext(MenuContext);
  const rest = omit(props, "render", "class", "children");
  // no `data-part` of its own: the part renders a `Button`, which owns the attribute, as `Dialog.Trigger` does
  const merged = merge(rest, menu.triggerProps, () => ({
    get class() {
      return css.cn(props.class);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <Button {...part}>{props.children}</Button>
  ));
};

/**
 * The list, floating under the trigger. Nothing is measured: it is absolute in the anchor. The primitive reports which
 * row holds the tab stop, and this moves the DOM focus there, so an arrow key lands somewhere — the same split as Tabs.
 */
export const MenuContent = (props: MenuContentProps): JSX.Element => {
  const { menu } = useContext(MenuContext);
  // The primitive reports which part holds the focus (`focusLevel` + `focusIndex`); the kit moves the DOM focus there by
  // the part's id, so a `render` that renames or re-tags a row cannot break the movement.
  createEffect(
    () => [menu.focusLevel(), menu.focusIndex()] as const,
    ([level, index]) => {
      const element =
        level === 1
          ? byId(menu.triggerProps.id)
          : level === 2
            ? byId(menu.items[index]?.id ?? "")
            : undefined;
      if (element !== undefined && document.activeElement !== element) {
        element.focus();
      }
    },
  );
  // the primitive's `ref` builds the list's focusgroup and registers its own keydown listener (typeahead included) before
  // the provider's, so the kit hands the keys to it and keeps none of its own
  const merged = merge(menu.menuProps, () => ({
    "data-part": "menu",
    get class() {
      return css.cn(contentClass, props.class);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <div {...part}>
      {props.children ?? menu.items.map((_, index) => <MenuItem index={index} />)}
    </div>
  ));
};

/**
 * One row: its role (`menuitem`, `menuitemcheckbox` or `menuitemradio`), id and focus handling from the primitive, the
 * declared label unless `children` says. A checkable row paints the check from its announced `aria-checked`, not from a
 * kit copy, and the highlight from `data-highlighted` — the row the primitive's roving focus sits on.
 */
export const MenuItem = (props: MenuItemProps): JSX.Element | null => {
  const { menu, checkable } = useContext(MenuContext);
  const declared = menu.items[props.index];
  if (declared === undefined) {
    return null;
  }
  const state: MenuItemState = {
    highlighted: () => menu.focusLevel() === 2 && menu.focusIndex() === props.index,
    disabled: () => declared.disabled,
    checked: () => menu.itemProps(props.index)["aria-checked"] === "true",
  };
  const merged = merge(menu.itemProps(props.index), () => ({
    "data-part": "menu-item",
    get "data-highlighted"() {
      return state.highlighted() ? "true" : undefined;
    },
    get class() {
      return css.cn(itemClass, props.class);
    },
  }));
  return renderPart(props, merged, state, (part) => (
    // a `<button>`: the row must be focusable for the platform to move focus to it (the native engine writes no tabindex)
    <button type="button" {...part}>
      {checkable ? (
        <span aria-hidden="true" class={markClass}>
          ✓
        </span>
      ) : undefined}
      {props.children ?? declared.label}
    </button>
  ));
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import type { MenuButtonConfig } from "@cssints/apg-specs/apg/menu-button.bridge";
import type { MenuCheckableConfig } from "@cssints/apg-specs/apg/menu-checkable.bridge";
import { type Menu as MenuController } from "@cssints/headless";
import type { Json } from "@cssints/apg-specs/scenario";
import type { PartProps } from "./render.tsx";
import type { Mounted } from "./menu-driver.ts";
import { Menu, MenuContent, MenuItem, MenuTrigger } from "./menu.tsx";
import { createSignal } from "solid-js";
import { render } from "@solidjs/web";
import type { JSX } from "@solidjs/web";

/**
 * Solid 2's `userEvent` fires Enter's default click after the keydown, and re-checks the focused element to
 * find it. The kit closes the menu and returns the focus to the trigger in the same flush, so that click lands
 * on the trigger and reopens the menu; a real browser keeps the click on the row it was pressed on. This
 * swallows only that synthesized click (bean 209r in `packages/headless`), not a reader's.
 */
const guardEnterOnItem = (root: HTMLElement): (() => void) => {
  let fromItem = false;
  const onKeyDown = (event: KeyboardEvent): void => {
    if (event.key !== "Enter") {
      return;
    }
    const target = event.target;
    fromItem = target instanceof HTMLElement && target.dataset["part"] === "menuitem";
    if (fromItem) {
      setTimeout(() => {
        fromItem = false;
      }, 0);
    }
  };
  const onClick = (event: MouseEvent): void => {
    const target = event.target;
    if (fromItem && target instanceof HTMLElement && target.dataset["part"] === "trigger") {
      event.preventDefault();
      event.stopPropagation();
      fromItem = false;
    }
  };
  root.addEventListener("keydown", onKeyDown, true);
  root.addEventListener("click", onClick, true);
  return () => {
    root.removeEventListener("keydown", onKeyDown, true);
    root.removeEventListener("click", onClick, true);
  };
};

const asRecord = (value: Json | undefined): Record<string, Json> => {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new Error(`expected an object, got ${JSON.stringify(value)}`);
  }
  return value as Record<string, Json>;
};

/**
 * The walk's `key` steps are programmatic and its probe reads the rendered `tabindex`: they become a real
 * keydown where the user's finger is, and the fixture runs the kit on the forced polyfill, because the native
 * engine ignores an untrusted `keydown` and writes no tabindex (`menu.browser.test.tsx` covers that path).
 */
const pressKey = (target: HTMLElement | undefined, key: string): void => {
  target?.dispatchEvent(
    new KeyboardEvent("keydown", {
      key: key === "Space" ? " " : key,
      bubbles: true,
      cancelable: true,
    }),
  );
};

const rowsOf = (root: HTMLElement): HTMLElement[] => [
  ...root.querySelectorAll<HTMLElement>('[data-part="menuitem"]'),
];

/**
 * The kit's trigger and rows are named for the skin (`button`, `menu-item`); the shared DOM driver finds a
 * part by the spec's name, so the conformance fixture renames them through the components' own `render`
 * props. The trigger stays the kit's `Button` (its class and behaviour), with `data-part="trigger"` on the
 * element it renders.
 */
const triggerRender = (part: PartProps): JSX.Element => (
  <button {...part} data-part="trigger" type="button">
    Menu
  </button>
);

/** The rows and the list, rendered inside the `Menu` so they are inside its context. */
const contentRender =
  (labels: ReadonlyArray<string>) =>
  (part: PartProps): JSX.Element =>
    (
      // `tabindex="-1"`: the spec drives some keys at the menu container, which a scenario focuses; a
      // menu is focusable in the APG pattern (the kit itself leaves DOM focus on the rows, which the
      // fixture renames).
      <div {...part} tabindex={-1} data-part="menu">
        {labels.map((label, index) => (
          <MenuItem
            index={index}
            render={(row) => (
              <div {...row} data-part="menuitem">
                {label}
              </div>
            )}
          />
        ))}
      </div>
    );

/** The spec's packed `checked(wrap, choice)` as the kit's readable pair. */
const readable = (packed: number): { checked: ReadonlyArray<number>; radio: number } => ({
  checked: packed >= 5 ? [0] : [],
  radio: packed % 5 === 0 ? -1 : (packed % 5) - 1,
});

/**
 * Renders the checkable menu (`menu-checkable.qnt`) through the kit's `Menu`: the `mixed` variant gives item 1
 * a `menuitemcheckbox`, items 2-4 one `menuitemradio` group and item 5 a plain `menuitem`. DOM focus is the
 * primitive's (the kit moves it too, but the fixture may rename the rows the kit looks for, so the walk reads
 * the primitive's own level). Controlled, the fixture is the host: it keeps the packed value in a signal and
 * either writes every request back (`accepts`) or ignores it.
 */
export const mountCheckableMenu = (config: MenuCheckableConfig): Mounted => {
  const root = document.createElement("div");
  document.body.append(root);
  const events = new Map<string, Json[]>();
  const push = (name: string, payload: Json): void => {
    events.set(name, [...(events.get(name) ?? []), payload]);
  };
  const [host, setHost] = createSignal(config.value);
  let api: MenuController | undefined;
  // the primitive reports the readable pair; the ported scenarios assert the primitive's own item callbacks, so
  // the fixture derives them from the pair (a checkbox's change is the index whose bit moved)
  let previous = readable(config.value);

  const dispose = render(() => {
    return (
      <Menu
        items={config.items}
        variant={config.variant}
        disabled={config.disabled}
        provider="polyfill"
        value={config.controlled ? readable(host()) : undefined}
        onReady={(menu) => {
          api = menu;
        }}
        onOpenChange={(open) => {
          push("onOpenChange", open);
        }}
        onItemClick={(index) => {
          push("onItemClick", `menuitem:${index}`);
        }}
        onValueChange={(next) => {
          const before = new Set(previous.checked);
          const after = new Set(next.checked);
          const added = next.checked.find((index) => !before.has(index));
          const removed = previous.checked.find((index) => !after.has(index));
          const toggled = added ?? removed;
          if (toggled !== undefined) {
            // the ported checkable scenarios assert the latest checked value
            events.set("onCheckedChange", [added !== undefined]);
          }
          if ((next.radio ?? -1) !== previous.radio && (next.radio ?? -1) >= 0) {
            events.set("onValueChange", [(next.radio ?? -1) + 1]);
          }
          previous = { checked: [...next.checked], radio: next.radio ?? -1 };
          if (config.accepts) {
            const packed =
              (next.checked.includes(0) ? 5 : 0) +
              ((next.radio ?? -1) < 0 ? 0 : (next.radio ?? 0) + 1);
            setHost(packed);
          }
        }}
      >
        <MenuTrigger render={triggerRender} />
        <MenuContent render={contentRender(config.items)} />
      </Menu>
    );
  }, root);

  // `triggerMode: "held"`: a checkable menu's trigger holds focus while closed, which is the closed
  // level the spec's `focus` observation names. Written after `render`, outside the component's owner.
  api?.focusTrigger();
  const unguard = guardEnterOnItem(root);

  return {
    root,
    events,
    setProp: (name, value) => {
      switch (name) {
        case "focus":
          api?.focusTrigger();
          break;
        case "key": {
          const record = asRecord(value);
          if (typeof record["key"] !== "string") {
            throw new Error(`key needs a string, got ${JSON.stringify(value)}`);
          }
          // the checkable menu's level 1 is the trigger (it holds focus while closed)
          const level = api?.focusLevel();
          pressKey(
            level === 2
              ? rowsOf(root)[api?.focusIndex() ?? 0]
              : level === 1
                ? (root.querySelector<HTMLElement>('[data-part="trigger"]') ?? undefined)
                : undefined,
            record["key"],
          );
          break;
        }
        case "setValue":
          setHost(Number(value));
          break;
        case "hostToggle":
          setHost((packed) => (packed >= 5 ? packed - 5 : packed + 5));
          break;
        default:
          throw new Error(`fixture has no prop ${name}`);
      }
    },
    focus: () => {
      const level = api?.focusLevel();
      if (level === 1) {
        return "trigger";
      }
      if (level === 2) {
        return `menuitem:${api?.focusIndex()}`;
      }
      return null;
    },
    dispose: () => {
      unguard();
      dispose();
      root.remove();
    },
  };
};

/**
 * Renders the flat menu button (`menu-button.qnt`) through the kit's `Menu`: one trigger, a four-item list, and
 * the third item (DOM index 2) disabled, which is the spec's fixed fixture. Controlled, the fixture is the host:
 * it keeps the open state in a signal, passes it as `open`, and either writes every request back (`accepts`) or
 * ignores it.
 */
export const mountMenuButton = (config: MenuButtonConfig): Mounted => {
  const root = document.createElement("div");
  document.body.append(root);
  const events = new Map<string, Json[]>();
  const push = (name: string, payload: Json): void => {
    events.set(name, [...(events.get(name) ?? []), payload]);
  };
  const [host, setHost] = createSignal(config.value);
  let api: MenuController | undefined;

  const dispose = render(() => {
    return (
      <Menu
        items={config.items}
        variant="plain"
        disabled={config.disabled}
        provider="polyfill"
        open={config.controlled ? host() : undefined}
        onReady={(menu) => {
          api = menu;
        }}
        onOpenChange={(open) => {
          push("onOpenChange", [open]);
          if (config.controlled && config.accepts) {
            setHost(open);
          }
        }}
        onItemClick={(index) => {
          push("onItemClick", [`menuitem:${index}`]);
        }}
      >
        <MenuTrigger render={triggerRender} />
        <MenuContent render={contentRender(config.items)} />
      </Menu>
    );
  }, root);

  const unguard = guardEnterOnItem(root);

  return {
    root,
    events,
    setProp: (name, value) => {
      switch (name) {
        case "focus":
          api?.focusTrigger();
          break;
        case "leave":
        case "blur":
          api?.leave();
          break;
        case "key": {
          const record = asRecord(value);
          if (typeof record["key"] !== "string") {
            throw new Error(`key needs a string, got ${JSON.stringify(value)}`);
          }
          // the checkable menu's level 1 is the trigger (it holds focus while closed)
          const level = api?.focusLevel();
          pressKey(
            level === 2
              ? rowsOf(root)[api?.focusIndex() ?? 0]
              : level === 1
                ? (root.querySelector<HTMLElement>('[data-part="trigger"]') ?? undefined)
                : undefined,
            record["key"],
          );
          break;
        }
        case "typeahead":
          api?.typeaheadCode(Number(value));
          break;
        case "type":
          api?.type(String(value));
          break;
        case "setValue":
          if (typeof value !== "boolean") {
            throw new Error(`setValue needs a boolean, got ${JSON.stringify(value)}`);
          }
          setHost(value);
          break;
        case "hostToggle":
          setHost((open) => !open);
          break;
        default:
          throw new Error(`fixture has no prop ${name}`);
      }
    },
    focus: () => {
      const level = api?.focusLevel();
      if (level === 1) {
        return "trigger";
      }
      if (level === 2) {
        return `menuitem:${api?.focusIndex()}`;
      }
      return null;
    },
    dispose: () => {
      unguard();
      dispose();
      root.remove();
    },
  };
};

import { type ActionStep, type Driver, type Json, Unsupported } from "@cssints/apg-specs/scenario";
import { flush } from "solid-js";
import { userEvent } from "vite-plus/test/browser";

/**
 * The generic DOM side of the scenario bridge. A pattern's fixture renders its
 * parts with `data-part="<name>"` and returns a `Mounted`; this turns scenario
 * steps into real pointer/keyboard input and DOM reads into observations.
 */
export interface Mounted {
  readonly root: HTMLElement;
  /** Apply a scenario `prop` step (programmatic input) to the mounted widget. */
  readonly setProp: (name: string, value: Json | undefined) => void;
  /** Callback payloads, recorded under their canonical name. */
  readonly events: ReadonlyMap<string, ReadonlyArray<Json>>;
  readonly value?: () => Json;
  /**
   * The part the primitive itself considers focused (`trigger`, `tab:1`), or
   * `null`. Preferred over `document.activeElement` so the walk does not race the
   * fixtures' deferred DOM focus (bean 209r).
   */
  readonly focus?: () => string | null;
  readonly dispose: () => void;
}

export interface DomDriverOptions {
  /** Parts that can be hidden: the ones `expect.visible` lists. */
  readonly hideableParts: ReadonlyArray<string>;
  readonly eventName?: (name: string) => string;
}

const BOOLEAN_ATTRS = new Set(["hidden", "disabled"]);
const REFERENCE_ATTRS = new Set([
  "aria-controls",
  "aria-labelledby",
  "aria-owns",
  "aria-activedescendant",
]);
const NAMED_KEYS = new Set(["Enter", "Tab", "Escape", "Backspace", "Delete", "Home", "End"]);

// Solid renders on its own schedule, but `flush()` applies the queued signal work
// synchronously; the fixtures then move DOM focus in a `setTimeout(0)` macrotask
// (kept for user-event's Enter semantics). Waiting one macrotask lets both land
// before the walk reads, without a frame — a frame also lets the browser's focus
// fixup run and perturb the observation (bean 209r). The walk reads focus from
// the fixture's primitive state when it offers one (`Mounted.focus`).
const settle = (): Promise<void> => {
  flush();
  return new Promise((resolve) => {
    setTimeout(resolve, 0);
  });
};

const keyboardSyntax = (key: string): string => {
  if (key === "Space" || key === " ") {
    return " ";
  }
  return NAMED_KEYS.has(key) || key.startsWith("Arrow") || key.startsWith("Page")
    ? `{${key}}`
    : key;
};

// A held key is always written by name: `{Space>}` keeps it down, `{/Space}`
// releases it wherever focus is at that moment (a blur between the two halves
// is exactly what a walk needs to see).
const keyName = (key: string) => (key === " " || key === "Space" ? "Space" : key);

/** `KeyboardEvent.key` uses a space character, not the `Space` alias. */
const eventKey = (key: string) => (key === "Space" ? " " : key);

const CLICKABLE_INPUT_TYPES = new Set([
  "button",
  "color",
  "file",
  "image",
  "reset",
  "submit",
  "checkbox",
  "radio",
]);

/**
 * A half press is dispatched directly (not through user-event's held-key state,
 * which auto-releases on a repeated down and leaks across walk drivers). The
 * two native activations user-event would otherwise add are emulated: Space
 * clicks a button-like element on keyup, Enter on keydown.
 */
const halfPress = (target: EventTarget | null, type: "keydown" | "keyup", key: string) => {
  if (!(target instanceof HTMLElement)) {
    return;
  }
  const keyValue = eventKey(key);
  const notPrevented = target.dispatchEvent(
    new KeyboardEvent(type, {
      key: keyValue,
      code: keyName(key),
      bubbles: true,
      cancelable: true,
    }),
  );
  const clickable =
    target.tagName === "BUTTON" ||
    (target instanceof HTMLInputElement && CLICKABLE_INPUT_TYPES.has(target.type));
  if (
    notPrevented &&
    clickable &&
    ((type === "keyup" && keyValue === " ") || (type === "keydown" && keyValue === "Enter"))
  ) {
    target.click();
  }
};

export const domDriver = (mounted: Mounted, options: DomDriverOptions): Driver => {
  const { root } = mounted;
  const canonical = options.eventName ?? ((name: string) => name);

  const partsOf = (name: string): HTMLElement[] => [
    ...root.querySelectorAll<HTMLElement>(`[data-part="${name}"]`),
  ];

  const targetOf = (element: HTMLElement): string => {
    const name = element.dataset["part"] ?? "";
    return `${name}:${partsOf(name).indexOf(element)}`;
  };

  const elementOf = (target: string): HTMLElement => {
    const [name = "", index = "0"] = target.split(":");
    const element = partsOf(name)[Number(index)];
    if (element === undefined) {
      throw new Unsupported(`part ${target}`);
    }
    return element;
  };

  const click = async (element: HTMLElement): Promise<void> => {
    // a disabled button is not actionable; force lets the browser drop the click itself
    await userEvent.click(element, { force: true });
  };

  // Half presses this driver dispatched a keydown for, so a stray `phase: "up"`
  // stays inert (the spec's key_up only fires on an armed press).
  const halfHeld = new Set<string>();

  return {
    perform: async (step: ActionStep) => {
      switch (step.event) {
        case "focus":
          elementOf(step.target ?? "").focus();
          break;
        case "blur":
          halfHeld.clear();
          elementOf(step.target ?? "").blur();
          break;
        case "click":
          await click(elementOf(step.target ?? ""));
          break;
        case "pointerdown":
          elementOf(step.target ?? "").focus();
          elementOf(step.target ?? "").dispatchEvent(
            new PointerEvent("pointerdown", {
              bubbles: true,
              cancelable: true,
              pointerType: step.pointerType ?? "mouse",
            }),
          );
          break;
        case "pointerup": {
          const element = elementOf(step.target ?? "");
          element.dispatchEvent(
            new PointerEvent("pointerup", {
              bubbles: true,
              cancelable: true,
              pointerType: step.pointerType ?? "mouse",
            }),
          );
          // a released pointer button is a click, as the browser would deliver it
          element.click();
          break;
        }
        case "pointercancel":
          elementOf(step.target ?? "").dispatchEvent(
            new PointerEvent("pointercancel", {
              bubbles: true,
              cancelable: true,
              pointerType: step.pointerType ?? "mouse",
            }),
          );
          break;
        case "hover":
          await userEvent.hover(elementOf(step.target ?? ""));
          break;
        case "unhover":
          await userEvent.unhover(elementOf(step.target ?? ""));
          break;
        case "key": {
          if (step.phase === "down") {
            const element = elementOf(step.target ?? "");
            if (document.activeElement !== element) {
              element.focus();
            }
            // a disabled/read-only control never arms (the spec's spaceArms
            // guard), so a later `up` must not activate it either
            const blocked =
              element.getAttribute("aria-disabled") === "true" ||
              element.getAttribute("aria-readonly") === "true" ||
              (element instanceof HTMLButtonElement && element.disabled);
            if (!blocked) {
              halfHeld.add(keyName(step.key ?? ""));
            }
            halfPress(element, "keydown", step.key ?? "");
            break;
          }
          if (step.phase === "up") {
            if (!halfHeld.delete(keyName(step.key ?? ""))) {
              break;
            }
            // release wherever focus went: deliberately do NOT re-focus the
            // target, or a keydown -> blur -> keyup walk would be defeated
            const active = document.activeElement;
            halfPress(
              active instanceof HTMLElement ? active : document.body,
              "keyup",
              step.key ?? "",
            );
            break;
          }
          const element = elementOf(step.target ?? "");
          if (document.activeElement !== element) {
            element.focus();
          }
          // a whole press releases the key, so a later `phase: "up"` is inert
          halfHeld.delete(keyName(step.key ?? ""));
          await userEvent.keyboard(keyboardSyntax(step.key ?? ""));
          break;
        }
        case "prop":
          if (step.set !== undefined) {
            for (const [name, value] of Object.entries(step.set)) {
              mounted.setProp(name, value);
              if ((name === "disabled" || name === "isDisabled") && value === true) {
                // the spec drops a pending press when the control disables
                halfHeld.clear();
              }
            }
          } else {
            mounted.setProp(step.prop ?? "", step.value);
            if ((step.prop === "disabled" || step.prop === "isDisabled") && step.value === true) {
              halfHeld.clear();
            }
          }
          break;
        default:
          throw new Unsupported(`event ${step.event}`);
      }
      await settle();
    },
    observer: {
      focus: () => {
        // Prefer the primitive's own focus: the fixtures sync DOM focus in a
        // deferred macrotask (kept for user-event's Enter semantics), so reading
        // `document.activeElement` here races that (bean 209r).
        if (mounted.focus !== undefined) {
          return mounted.focus();
        }
        const active = document.activeElement;
        const part =
          active instanceof HTMLElement ? active.closest<HTMLElement>("[data-part]") : null;
        return part !== null && root.contains(part) ? targetOf(part) : null;
      },
      attr: (target, name) => {
        if (name.startsWith("data-")) {
          throw new Unsupported(`styling hook ${name}`);
        }
        const value = elementOf(target).getAttribute(name);
        if (value === null) {
          return null;
        }
        if (value === "" && BOOLEAN_ATTRS.has(name)) {
          return "true";
        }
        if (REFERENCE_ATTRS.has(name)) {
          const referenced = root.querySelector<HTMLElement>(`[id="${value}"]`);
          return referenced?.dataset["part"] === undefined ? value : targetOf(referenced);
        }
        return value;
      },
      visible: () =>
        options.hideableParts.flatMap((name) =>
          partsOf(name)
            .filter((element) => element.checkVisibility())
            .map(targetOf),
        ),
      events: (name) => mounted.events.get(canonical(name)) ?? [],
      ...(mounted.value === undefined ? {} : { value: mounted.value }),
    },
    dispose: mounted.dispose,
  };
};

